$operator = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/me?$select=id' -ErrorAction Stop
$emergencyIds = @($body.conditions.users.excludeUsers)
if ($emergencyIds.Count -lt 2 -or @($emergencyIds | Select-Object -Unique).Count -lt 2) { throw 'Resolve two distinct emergency accounts.' }
$body.conditions.users.excludeUsers = @($emergencyIds + $operator.id | Select-Object -Unique)
$exclusionGroupId = Read-Host 'Exact reviewed user exclusion group ID'
$parsedGroup = [guid]::Empty; if (-not [guid]::TryParse($exclusionGroupId,[ref]$parsedGroup)) { throw 'Resolve the exclusion group first.' }
$body.conditions.users.excludeGroups = @(@($body.conditions.users.excludeGroups) + $exclusionGroupId | Where-Object { $_ } | Select-Object -Unique)
# Verify every user/group/location by exact ID before this reference is used. Do not replace or narrow other exclusions.
# Inspect existing objects and any name conflict before creation. A matching name is never permission to update/adopt.
Assert-ManualGraphTenant
$created = Invoke-MgGraphRequest -Method POST -Uri 'https://graph.microsoft.com/v1.0/identity/conditionalAccess/policies' -Body ($body | ConvertTo-Json -Depth 50) -ContentType 'application/json' -ErrorAction Stop
# Record the returned ID immediately. If the request is uncertain, stop and reconcile; do not send it again.
if (-not $created.id) { throw 'Returned ID unknown; reconcile without retrying creation.' }
Invoke-MgGraphRequest -Method GET -Uri ('https://graph.microsoft.com/v1.0/identity/conditionalAccess/policies/' + $created.id) -ErrorAction Stop | ConvertTo-Json -Depth 50

$dkim = Get-DkimSigningConfig -Identity $domain -ErrorAction Stop
$dkim | Format-List Name,Enabled,Status,Selector1CNAME,Selector2CNAME
foreach ($number in 1,2) {
    $name = 'selector' + $number + '._domainkey.' + $domain
    $expected = $dkim.('Selector' + $number + 'CNAME')
    if ([string]::IsNullOrWhiteSpace($expected)) { throw 'Actual CNAME target is unknown.' }
    $answer = @(Resolve-DnsName -Name $name -Type CNAME -DnsOnly -NoHostsFile -ErrorAction Stop | Where-Object { $_.Type.ToString() -eq 'CNAME' -and $_.Name.TrimEnd('.') -ieq $name })
    if ($answer.Count -ne 1 -or $answer[0].NameHost.TrimEnd('.') -ine $expected.TrimEnd('.')) { throw 'Both current CNAMEs must match their actual targets.' }
}
Assert-ManualTenant
Set-DkimSigningConfig -Identity $domain -Enabled $true -ErrorAction Stop
Get-DkimSigningConfig -Identity $domain | Format-List Name,Enabled,Status,Selector1CNAME,Selector2CNAME
